const arts = ($json.articles || []).map(a => `Fonte: ${a.source}\nURL: ${a.url}\nConteudo: ${a.text.slice(0, 2500)}`).join('\n\n---\n\n');
const userPrompt = `Topico em alta: ${$json.topic}\nVolume de busca: ${$json.traffic}\n\nArtigos relacionados:\n\n${arts}`;
const systemPrompt = "Voce e um editor de conteudo rigoroso, especializado em selecionar pautas para um assessor de investimentos que publica conteudo educativo/analitico no LinkedIn para atrair clientes de alto patrimonio. Voce recebe um topico em alta no Google Trends no Brasil e ate 3 artigos de noticia relacionados a ele, numerados por posicao no array (0, 1, 2). Sua tarefa: (1) avaliar se os artigos realmente tem relacao direta com o topico informado - se forem sobre assunto diferente ou muito generico, a nota deve ser baixa; (2) atribuir uma NOTA de 0 a 100 medindo o quanto esse topico tem substancia financeira/economica/de negocios genuina e potencial de virar um comentario natural (nao forcado) de um assessor de investimentos serio para investidores de alto patrimonio. Use como referencia: 90-100 noticia financeira/economica de primeira linha (resultado de empresa, decisao de politica monetaria, fusao/aquisicao, falencia, indicador economico) - conexao direta, sem forcar nada; 70-89 boa substancia financeira/de negocios, ainda que periferica, exigindo alguma traducao pro leitor; 50-69 relacao financeira fraca ou indireta - arriscado, provavelmente soa forcado; 0-49 sem substancia financeira real. Reduza a nota para no maximo 20 nos seguintes casos, MESMO que tecnicamente seja possivel inventar uma metafora financeira: (a) tragedia em andamento com sofrimento humano ativo - mortes recentes, desastres com vitimas, acidentes graves, crimes violentos, guerra ou conflito com baixas civis - nunca use morte, desastre ou sofrimento como gancho de marca, isso e antietico (newsjacking de tragedia); (b) topico centrado na vida pessoal, privada ou de consumo de uma celebridade ou figura publica - reforma ou compra de imovel, viagem, relacionamento, familia, saude, entrevista sobre tema nao financeiro, fofoca, novela, reality show, polemica de entretenimento, resultado esportivo sem repercussao financeira real - EXCETO se envolver acao financeira ou de negocio genuina da propria celebridade (empresa dela, investimento, falencia, fusao, IPO). Antes de dar uma nota alta, pergunte-se: um assessor de investimentos serio comentaria esse assunto publicamente para atrair clientes de alto patrimonio, ou pareceria forcado/oportunista? Na duvida, de nota mais baixa. (3) analisar cada um dos artigos individualmente e identificar APENAS os que realmente tratam do MESMO fato/acontecimento que justifica o topico - descarte artigos que apenas compartilham uma palavra, pessoa, instituicao ou categoria ampla, mas tratam de acontecimento diferente; retorne em fontes_validas os indices (0, 1 ou 2) apenas dos artigos genuinamente relacionados, do melhor pro pior; se nenhum artigo for realmente relacionado ao fato central, fontes_validas deve ser vazio e a nota deve ser baixa; (4) escrever um resumo objetivo (5 a 8 linhas) do que esta acontecendo, citando os fatos principais e as fontes validas; (5) sugerir um angulo especifico para conectar esse assunto ao universo de um assessor de investimentos atraves da lente de gestao de risco, decisao sob incerteza e disciplina comportamental - o angulo NUNCA pode soar como estar 'aproveitando' um evento triste ou a vida de um famoso, deve ser respeitoso e a conexao deve parecer natural, nunca forcada. NAO cite jogos de azar ou qualquer analogia explicita a jogo - a conexao deve ser feita apenas atraves desses conceitos (risco, incerteza, disciplina, comportamento), nunca citando a origem. Responda SOMENTE em JSON valido, sem markdown, sem crases, no formato exato: {\"nota\": 0 a 100, \"motivo\": \"...\", \"resumo\": \"...\", \"angulo_sugerido\": \"...\", \"fontes_validas\": [0,2,1]}";
return {
  json: {
    topicId: $json.topicId,
    topic: $json.topic,
    traffic: $json.traffic,
    articles: $json.articles,
    requestBody: {
      model: 'deepseek-chat',
      temperature: 0.3,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
};

const origin = $('04. Editor de Pauta - Montar Prompt').item.json;
let content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
content = content.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/, '').trim();
let parsed;
try { parsed = JSON.parse(content); } catch (e) { parsed = { nota: 0, motivo: 'Falha ao interpretar resposta da IA: ' + e.message, resumo: '', angulo_sugerido: '', fontes_validas: [] }; }

const nota = Number(parsed.nota) || 0;
const originalArticles = origin.articles || [];

const fontesValidasRaw = Array.isArray(parsed.fontes_validas) ? parsed.fontes_validas : [];
const fontesValidas = [...new Set(
  fontesValidasRaw
    .map(v => Number.parseInt(v, 10))
    .filter(i => Number.isInteger(i) && i >= 0 && i < originalArticles.length)
)].slice(0, 3);

const articlesValidados = fontesValidas.map(i => originalArticles[i]);

return {
  json: {
    topicId: origin.topicId,
    topic: origin.topic,
    traffic: origin.traffic,
    articles: articlesValidados.length > 0 ? articlesValidados : originalArticles,
    nota: nota,
    relevanteFlag: nota >= 70 ? 'sim' : 'nao',
    motivo_descarte: parsed.motivo || '',
    resumo: parsed.resumo || '',
    angulo_sugerido: parsed.angulo_sugerido || ''
  }
};

const resumo = $json.resumo || '';
const topic = $json.topic || '';
const anguloSugerido = $json.angulo_sugerido || '';

const systemPrompt = `Você é um especialista editorial que escolhe a melhor lente analítica para conectar uma notícia a conteúdo de um assessor de investimentos. Escolha UMA das cinco lentes abaixo, a que mais naturalmente se encaixa no tema (evite sempre escolher a mesma, cada tema pede uma lente diferente):

1. "gestao_de_risco_incerteza" — baseada na distinção de Frank Knight (1921) entre risco calculável e incerteza não-mensurável. Use quando o tema envolve decisões sob condições imprevisíveis.
2. "economia_comportamental" — baseada em vieses cognitivos (Kahneman, Tversky, Thaler): aversão à perda, excesso de confiança, ancoragem, viés de confirmação. Use quando o tema envolve decisões humanas questionáveis ou padrões de comportamento.
3. "geopolitica_macroeconomia" — Use quando o tema tem repercussão econômica ou política mais ampla.
4. "governanca_lideranca" — Use quando o tema envolve decisão institucional, organizacional ou de liderança sob pressão.
5. "planejamento_disciplina_pessoal" — Use quando o tema se conecta melhor a disciplina, paciência ou planejamento de longo prazo no nível individual.

Responda SOMENTE com um JSON no formato:
{"especialidade_editoria": "uma das cinco chaves acima", "justificativa": "explicação curta de por que essa lente encaixa melhor neste tema"}`;

const userPrompt = `Tópico: ${topic}\n\nResumo dos fatos:\n${resumo}\n\nÂngulo já sugerido anteriormente:\n${anguloSugerido}`;

return {
  json: {
    ...$json,
    requestBody: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.4
    }
  }
};

const origin = $('05. Especialista de Editoria - Montar Prompt').item.json;
const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    especialidade_editoria: 'gestao_de_risco_incerteza',
    justificativa: 'Erro ao interpretar resposta da IA, usando lente padrão: ' + e.message
  };
}

return {
  json: {
    ...origin,
    especialidade_editoria: parsed.especialidade_editoria,
    especialidade_justificativa: parsed.justificativa
  }
};
